<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { siteContentApi, type Article, type SiteMedia } from '@/l12/platform'
import OfficialNav from './OfficialNav.vue'
import { defaultHomeComposition, defaultSiteLegal, parseHomeComposition, parseSiteLegal, type HomeHeroSlide } from './homeContent'

const ready = ref(false)
const composition = ref(defaultHomeComposition())
const legal = ref(defaultSiteLegal())
const news = ref<Article[]>([])
const videos = ref<Article[]>([])
const products = ref<Article[]>([])
const media = ref<SiteMedia[]>([])
const activeIndex = ref(0)
let carouselTimer = 0

const enabledSlides = computed<HomeHeroSlide[]>(() => {
  const configured = composition.value.heroSlides.filter(item => item.enabled)
  return configured.length ? configured : [{
    id: 'brand-fallback', eyebrow: 'TWELVE LEGIONS · OFFICIAL', title: '十二军团',
    summary: '集结你的军团，构筑自己的神话，在官方线上对战平台展开战斗。',
    href: '/battle', linkLabel: '进入对战', mediaAssetId: '', enabled: true,
  }]
})
const activeSlide = computed(() => enabledSlides.value[activeIndex.value % enabledSlides.value.length]!)
const activeMedia = computed(() => media.value.find(item => item.id === activeSlide.value.mediaAssetId))
const activeNotices = computed(() => composition.value.notices.filter(item => item.enabled && item.label.trim()))
const leadNews = computed(() => news.value[0])
const moreNews = computed(() => news.value.slice(1, 6))

const isInternal = (href?: string) => Boolean(href?.startsWith('/') && !href.startsWith('//'))
const mediaFor = (article?: Article) => media.value.find(item => item.id === article?.mediaAssetId)
const articleHref = (article: Article, fallback: string) => article.link || fallback
const dateLabel = (article: Article) => new Date(article.publishedAt || article.publishAt || article.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit' })

function showSlide(index: number) { activeIndex.value = (index + enabledSlides.value.length) % enabledSlides.value.length }
function startCarousel() {
  window.clearInterval(carouselTimer)
  if (enabledSlides.value.length < 2 || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return
  carouselTimer = window.setInterval(() => showSlide(activeIndex.value + 1), 6500)
}

onMounted(async () => {
  try {
    const payload = await siteContentApi.home()
    composition.value = parseHomeComposition(payload.composition)
    legal.value = parseSiteLegal(payload.legal)
    news.value = payload.news; videos.value = payload.videos; products.value = payload.products; media.value = payload.media
  } catch {
    composition.value = defaultHomeComposition(); legal.value = defaultSiteLegal()
  } finally { ready.value = true; startCarousel() }
})
onBeforeUnmount(() => window.clearInterval(carouselTimer))
</script>

<template>
  <div v-if="ready" class="official-home">
    <header class="official-topbar"><router-link class="official-wordmark" to="/"><img src="/favicon.png" alt="十二军团"><span><b>十二军团</b><small>TWELVE LEGIONS</small></span></router-link><OfficialNav/></header>

    <section class="hero-section" aria-roledescription="carousel" aria-label="首页主视觉">
      <div class="hero-stage" :class="{ 'has-art': activeMedia }">
        <picture v-if="activeMedia" :key="activeMedia.id"><source media="(max-width: 760px)" :srcset="activeMedia.mobileUrl"><img :src="activeMedia.desktopUrl" :alt="activeMedia.altText || activeSlide.title"></picture>
        <div class="hero-fallback" aria-hidden="true"><i/><i/><i/></div>
        <div class="hero-shade"/>
        <div class="hero-copy"><small>{{ activeSlide.eyebrow }}</small><h1>{{ activeSlide.title }}</h1><p>{{ activeSlide.summary }}</p><router-link v-if="isInternal(activeSlide.href)" :to="activeSlide.href">{{ activeSlide.linkLabel || '了解更多' }}<b>→</b></router-link><a v-else :href="activeSlide.href || '#news'" target="_blank" rel="noopener">{{ activeSlide.linkLabel || '了解更多' }}<b>→</b></a></div>
        <div v-if="enabledSlides.length > 1" class="carousel-controls"><button aria-label="上一张" @click="showSlide(activeIndex - 1)">‹</button><span><button v-for="(_, index) in enabledSlides" :key="index" :class="{ active: index === activeIndex }" :aria-label="`显示第 ${index + 1} 张`" @click="showSlide(index)"/></span><button aria-label="下一张" @click="showSlide(activeIndex + 1)">›</button></div>
        <nav v-if="activeNotices.length" class="hero-notices" aria-label="重要通知"><template v-for="item in activeNotices" :key="item.id"><router-link v-if="isInternal(item.href)" :to="item.href" :data-tone="item.tone"><i>!</i>{{ item.label }}<b>↗</b></router-link><a v-else :href="item.href" target="_blank" rel="noopener" :data-tone="item.tone"><i>!</i>{{ item.label }}<b>↗</b></a></template></nav>
      </div>
    </section>

    <section id="news" class="news-section">
      <header class="section-heading"><div><small>{{ composition.newsEyebrow }}</small><h2>{{ composition.newsTitle }}</h2></div><p>{{ composition.newsDescription }}</p><router-link to="/news">资讯一览 <b>→</b></router-link></header>
      <div v-if="leadNews" class="news-stream">
        <component :is="isInternal(articleHref(leadNews, '/news')) ? 'router-link' : 'a'" class="lead-news" :to="isInternal(articleHref(leadNews, '/news')) ? articleHref(leadNews, '/news') : undefined" :href="isInternal(articleHref(leadNews, '/news')) ? undefined : articleHref(leadNews, '/news')" :target="isInternal(articleHref(leadNews, '/news')) ? undefined : '_blank'" rel="noopener">
          <picture v-if="mediaFor(leadNews)"><source media="(max-width: 760px)" :srcset="mediaFor(leadNews)?.mobileUrl"><img :src="mediaFor(leadNews)?.desktopUrl" :alt="leadNews.title"></picture><img v-else-if="leadNews.coverUrl" :src="leadNews.coverUrl" :alt="leadNews.title"><div class="news-placeholder" v-else><span>L12</span></div>
          <div><small>{{ leadNews.category }} · {{ dateLabel(leadNews) }}</small><h3>{{ leadNews.title }}</h3><p>{{ leadNews.summary || leadNews.body }}</p><b>READ MORE →</b></div>
        </component>
        <div class="news-lines"><component :is="isInternal(articleHref(item, '/news')) ? 'router-link' : 'a'" v-for="item in moreNews" :key="item.id" :to="isInternal(articleHref(item, '/news')) ? articleHref(item, '/news') : undefined" :href="isInternal(articleHref(item, '/news')) ? undefined : articleHref(item, '/news')" :target="isInternal(articleHref(item, '/news')) ? undefined : '_blank'" rel="noopener"><time>{{ dateLabel(item) }}</time><em>{{ item.category }}</em><b>{{ item.title }}</b><span>→</span></component></div>
      </div>
      <div v-else class="section-empty"><b>NEWS DESK</b><span>正式资讯发布后将在这里连续呈现。</span></div>
    </section>

    <section class="community-video-section">
      <header class="section-heading inverse"><div><small>{{ composition.videoEyebrow }}</small><h2>{{ composition.videoTitle }}</h2></div><p>{{ composition.videoDescription }}</p></header>
      <div v-if="videos.length" class="video-ribbon"><component :is="isInternal(articleHref(item, '/news')) ? 'router-link' : 'a'" v-for="(item, index) in videos.slice(0, 3)" :key="item.id" :class="{ feature: index === 0 }" :to="isInternal(articleHref(item, '/news')) ? articleHref(item, '/news') : undefined" :href="isInternal(articleHref(item, '/news')) ? undefined : articleHref(item, '/news')" :target="isInternal(articleHref(item, '/news')) ? undefined : '_blank'" rel="noopener"><picture v-if="mediaFor(item)"><source media="(max-width: 760px)" :srcset="mediaFor(item)?.mobileUrl"><img :src="mediaFor(item)?.desktopUrl" :alt="item.title"></picture><img v-else-if="item.coverUrl" :src="item.coverUrl" :alt="item.title"><div class="video-placeholder" v-else/><i>▶</i><span><small>{{ item.category }}</small><b>{{ item.title }}</b><em>{{ item.summary }}</em></span></component></div>
      <div v-else class="section-empty inverse"><b>COMMUNITY MOVIE</b><span>社群视频发布后将在这里出现。</span></div>
    </section>

    <section class="products-section">
      <header class="section-heading"><div><small>{{ composition.productEyebrow }}</small><h2>{{ composition.productTitle }}</h2></div><p>{{ composition.productDescription }}</p></header>
      <div v-if="products.length" class="product-track"><component :is="isInternal(articleHref(item, '/cards')) ? 'router-link' : 'a'" v-for="item in products" :key="item.id" :to="isInternal(articleHref(item, '/cards')) ? articleHref(item, '/cards') : undefined" :href="isInternal(articleHref(item, '/cards')) ? undefined : articleHref(item, '/cards')" :target="isInternal(articleHref(item, '/cards')) ? undefined : '_blank'" rel="noopener"><picture v-if="mediaFor(item)"><source media="(max-width: 760px)" :srcset="mediaFor(item)?.mobileUrl"><img :src="mediaFor(item)?.desktopUrl" :alt="item.title"></picture><img v-else-if="item.coverUrl" :src="item.coverUrl" :alt="item.title"><div class="product-placeholder" v-else><span>12</span></div><small>{{ item.category }}</small><h3>{{ item.title }}</h3><p>{{ item.summary }}</p><b>查看详情 →</b></component></div>
      <div v-else class="section-empty"><b>PRODUCT INFORMATION</b><span>商品情报发布后将在这里出现。</span></div>
    </section>

    <footer class="official-footer"><router-link to="/"><img src="/favicon.png" alt="十二军团"><span>TWELVE LEGIONS</span></router-link><div><p>{{ legal.trademark }}</p><a v-if="legal.contactHref" :href="legal.contactHref" target="_blank" rel="noopener">{{ legal.contactLabel || '联系我们' }}</a><small>{{ legal.copyright }}<template v-if="legal.registration"> · {{ legal.registration }}</template></small></div></footer>
  </div>
  <div v-else class="official-home-loading" aria-label="正在加载官网内容"><i/><i/><i/></div>
</template>

<style scoped>
